const m=[{id:"stoic-epictetus-iep",title:"S09 · Seddon · Epiktetos · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/epictetu/",type:"guidance",finding:"Epiktetos, bize bağlı olanla olmayanı ayırarak çabamızı yargılarımıza, amaçlarımıza ve davranışlarımıza yöneltmemizi önerir. Bu, felsefi bir yol gösterme biçimidir.",limitation:"Tarih ve felsefe kaynağı. Düşünce ve davranışların bütünüyle irademizde olduğuna dair psikolojik kanıt değil. Engellilik, hastalık, baskı ve eldeki imkânlar yapabileceklerini sınırlar."},{id:"stoic-seneca-iep",title:"S10 · Wagoner · Seneca · Internet Encyclopedia of Philosophy",url:"https://iep.utm.edu/seneca/",type:"guidance",finding:"Seneca öfkeyi anlatırken kendiliğinden gelen ilk tepkiyle sonradan o tepkiyi benimsemeyi birbirinden ayırır.",limitation:"Tarihsel felsefe; duyguları bütünüyle açıklayan, doğrulanmış bir model değil. Panik veya travma belirtilerini seçerek yok edebileceğin ya da bunların ahlaki bir kusur olduğu anlamına gelmez."},{id:"stoic-week-handbook",title:"S08 · Stoicism Today · Stoic Week 2016 el kitabı",url:"https://modernstoicism.com/wp-content/uploads/2016/10/Stoic-Week-2016-Handbook-Stoicism-Today.pdf",type:"technique",finding:"Kontrol ayrımını, zorluklara hazırlanmayı, daha geniş açıdan bakmayı ve yatağa girmeden önce beş ile on dakikalık adil akşam değerlendirmesini anlatır.",limitation:"Uygulayıcı el kitabı. Tek tek ritüellerin veya en iyi sürelerin deneyi değil. Kontrolü ayırma, olumsuz canlandırma, uzaydan dünyaya bakma ve akşam değerlendirmesi için bağımsız etki doğrulanmadı."},{id:"stoic-planning",title:"S03 · Gollwitzer ve Sheeran · 2006 · Şu olursa bunu yaparım planları",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 katılımcılı 94 bağımsız sınamada belirli bir durumu belirli davranışla eşleştiren planlar hedefe ulaşmada ortalama fayda gösterdi: d = 0,65 [0,60, 0,70].",limitation:"Hedefler, tasarımlar ve karşılaştırmalar farklıydı. Yalnızca güncel, önceden kaydedilmiş rastgele atamalı deneyler yoktu. Bu sayı başarı yüzdesi, garanti veya olumsuz canlandırmanın kanıtı değil."},{id:"stoic-mcii",title:"S04 · Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve planlama",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 makalede 15.907 katılımcıdan 24 bağımsız tahmin birleştirildi. İstenen sonuç, mevcut engel ve şu olursa bunu yaparım planı, hedefe ulaşmada ortalama g = 0,336 [0,229, 0,443] gösterdi.",limitation:"Çalışmalar arası ciddi farklılık, I² = %59,3, ve değişen kalite tahminin kesinliğini sınırlar. Olumsuz canlandırmayı tek başına sınamaz, her hedefin yapılabilir olduğunu kanıtlamaz veya ODA’nın kısa uyarlamasını doğrulamaz."},{id:"stoic-thought-record",title:"S11 · NHS · Düşünce kaydı · Every Mind Matters",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/thought-record/",type:"guidance",finding:"Yedi soru; durumu, duyguları, düşünceyi, destekleyen kanıtı, karşı kanıtı, gerçekçi alternatifi ve sonraki duyguları ayırır. Tarafsız bir sonuç uygun olabilir.",limitation:"Resmî kişisel destek rehberi. Tek başına etki büyüklüğünü ölçen çalışma değil. Olumlu düşünmeyi veya gerçekten kötü davranılmış olmasını zararsız diye yorumlamayı gerektirmez."},{id:"stoic-cbt",title:"S01 · Hofmann ve diğerleri · 2012 · BDT meta-analizleri derlemesi",url:"https://www.europsy.net/app/uploads/2017/08/Hofmann-2012-The-efficacy-of-CBT-a-review-of-meta-analyses.pdf",type:"research",finding:"Yazarlar 269 meta-analiz bulup bunların temsili 106’sını ele aldı. Bazı kaygı sorunları, öfke ve stres için soruna özgü güçlü tedavi kanıtları anlattı.",limitation:"Tek bir birleşik BDT etkisi veya katılımcı sayısı vermeyen anlatı derlemesi. Tedavi kanıtı Stoacı derse aktarılamaz; kısa bir düşünce kaydının etkisini tek başına göstermez."},{id:"stoic-kross-self-talk",title:"S05 · Kross ve diğerleri · 2014 · Kendinle konuşma biçimi",url:"https://rascl.berkeley.edu/assets/files/self-talk_as_a_regulatory_mechanism_how_you_do_it_matters.pdf",type:"research",finding:"Toplam 585 katılımcılı yedi çalışma, kişinin kendini birinci kişi dışında anlatmasını inceledi. 1a çalışmasında 60 saniye düşünmenin ardından katılımcılar daha fazla mesafe aldıklarını bildirdi.",limitation:"Tek araştırma programındaki birbirini destekleyen deneyler. Yedi bağımsız klinik deney değil. Kendi adını kullanmak kanıtlanmış tedavi değil; ODA’nın hafif, güncel durum alıştırması bir uyarlama."},{id:"stoic-kross-distancing",title:"S06 · Murdoch ve diğerleri · 2023 · Mesafeden düşünme meta-analizi",url:"https://onlinelibrary.wiley.com/doi/full/10.1002/smi.3199",type:"research",finding:"17 makalede 2.397 katılımcılı 25 deney, farklı sonuçlar genelinde mütevazı bir birleşik etki buldu: g = 0,19 [0,05, 0,33].",limitation:"Çoğunlukla genç, görünürde sağlıklı yetişkinler. Kalite belirsiz; çalışmalar ciddi ölçüde farklı. Tahmin aralığı sıfırı kapsadı. Nesnel sonuçlarda istatistiksel olarak anlamlı fark bulunmadı; uzaydan dünyaya bakma veya on yıl sonrasını düşünme alıştırmaları tek başına sınanmadı."},{id:"stoic-distancing-sleep",title:"S16 · Riddell ve diğerleri · 2023 · Stresi düşünme ve uyku",url:"https://onlinelibrary.wiley.com/doi/10.1002/smi.3201",type:"research",finding:"Önceden kaydedilmiş deney, mesafeden düşünmenin uykuya faydasını desteklemedi. Uyku kalitesindeki değişim olaya kendi gözünden bakan grubu destekledi; uyku süresinde istatistiksel olarak anlamlı fark bulunmadı.",limitation:"Başlangıçta 318 kişi vardı; 257 kişi analiz edildi. Mesafeden düşünme grubundan 51 kişi birinci kişiyle yazdığı için çıkarıldı. Tablo ve anlatımdaki çelişkili işaretler, iyi oluşun değişim yönü hakkında iddiaya izin vermiyor."},{id:"stoic-training-trial",title:"S13 · Maclellan ve Derakshan · 2021 · Çok kaygılanan kişilerde eğitim",url:"https://link.springer.com/article/10.1007/s10608-020-10183-4",type:"research",finding:"Çok kaygılanan 45 kişi; sekiz oturumluk Stoacı eğitim, birleşik eğitim ve aktif one-back kontrolüne rastgele dağıtıldı. Özet, tekrarlayan düşüncelerde ve kişinin yapabileceğine inancında değişimler bildiriyor.",limitation:"Küçük çalışma; burada yalnızca özet erişilebildi. Kesin etkiler, güven aralıkları, ayrılan kişi sayısı ve kayıt doğrulanmadı. Tek bir ritüeli sınamaz; tanı konmuş kaygı için tedavi etkisi göstermez."},{id:"stoic-training-thesis",title:"S15 · King · 2025 · Modern Stoacılık ve ruh sağlığı tezi",url:"https://pure.royalholloway.ac.uk/en/publications/modern-stoicism-and-mental-health-a-randomised-controlled-trial/",type:"research",finding:"Klinik örneklem dışındaki 119 yetişkin, iki haftalık çevrim içi Stoacı eğitim veya bekleme listesine ayrıldı. Kurum özeti, bütün ölçümleri bulunan kişilerde bazı ruh sağlığı ölçümlerinde olumlu değişimler bildiriyor.",limitation:"Yayımlanmamış tek doktora tezi. Hakemli araştırmaların ortak tedavi sonucu değil. Tamamlayanların sayısı, etkiler, aralıklar ve kayıt doğrulanmadı. Bekleme listesi, tek ritüellerin etkisini veya psikoterapiyle eşdeğerliği göstermez."}],d=[{schemaVersion:2,revision:2,id:"stoic-1",courseId:"stoic",locale:"tr",title:"Yanıtı yine mi kontrol ediyorsun? Yapabileceğin işe dön.",goal:"Sonuç belirsizken seçtiğin hedefe yarayan somut bir iş yap.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Gelen kutusunu yine yeniledin mi? O dikkatin birazını hedefin için yapabileceğin işe ayır.",reason:{id:"stoic-1-reason",label:"Yanıtı beklerken hangi yararlı işi geri plana attın?",kind:"text",maxLength:160,optional:!0,suggestions:["Hedefimi somut bir işle desteklemek","İçim rahatlasın diye sürekli yenilemeyi bırakmak","İşe yarayan yardım istemek"]},why:{id:"stoic-1-why",label:"Yanıtı beklerken hangi yararlı işi geri plana attın?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Sonuç senin için önemli olabilir ama kararı tek başına sen veremezsin. Epiktetos bu ayrımla çabayı itibara veya sonuca değil, davranışa yöneltirdi. Bu bir felsefi öneri. Her düşünceyi ve hareketi bütünüyle seçebildiğinin kanıtı değil. Sağlık, baskı, engellilik ve eldeki imkânlar ne yapabileceğini sınırlayabilir. Bunları yok sayman gerekmiyor.","Kurs boyunca bir hedef ve ona yarayan bir işi deneyeceksin. Yapmayı deneyebileceğin işi, gereken desteği ve başkasının kararını ayır. Sonra sana uygun kısmını yap. İşverenden yanıt gelmese de portföyüne yazdığın cümle oradadır. Sonuçtan bilgi al; önemsemeyi bırakmak zorunda değilsin."],example:{title:"Kerem’in proje cümlesi",text:"Pazartesi öğle molasında Kerem başvuru için gelen kutusunu dört kez yenilediğini fark ediyor. İş ararken yaptığı projeleri somut biçimde göstermek istiyor. Masasında portföyüne bir cümle yazıyor. İyileştirdiği kontrol listesini ve nasıl kullanıldığını anlatıyor. Yazdığı cümleyi kaydediyor. Gelen kutusu hâlâ boş; belirsizlik de sürüyor. Ama yazdığı cümle başvurusuna ekleyebileceği gerçek bir parça."}},move:{invitation:"Sonuç hâlâ belirsizken hedefin için yapabileceğin yararlı bir iş seç.",instructions:["Yapabileceğin işi, gereken desteği ve sonucu ayır. Her şeyi kontrol etmen gerekmiyor.","Sana uygun kısmını yap ve ne yaptığını kaydet."],prompts:[],suggestions:{action:["Projede yaptığım işi anlatan bir cümle yaz","Uygun bir açıklama sorusu gönder","İşe yarayan bir destek iste"],minimum:["Kullanabileceğim bir proje cümlesi yaz","Açık bir soru gönder","Belirli bir konuda destek iste"],cue:["Öğle molasından döndüğümde","Sonraki güvenli fırsatta","Projenin sıradaki işinden önce"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["Cümleyi sesli notla anlat","İşe yarayan daha küçük bir katkı seç","Erişim için yardım iste"],observation:["Yazdığım işe yarar cümle","Gönderdiğim soru ve gelen yanıt","Hangi desteği istediğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Projede yaptığım işi anlatan bir cümle yaz",minimum:"Kullanabileceğim bir proje cümlesi yaz",minutes:2,cueHint:"Öğle molasından döndüğümde",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Enerjim veya kullanabildiğim imkânlar sınırlı.",fallbackHint:"Cümleyi sesli notla anlat",observationHint:"Yazdığım işe yarar cümle"},stopRule:"Tehlike varken uygulamayı sürdürme. Yapabileceklerin kısıtlıysa korunma veya destek ara.",accessibleAlternative:"Sesle yazdır, iletişim desteği al, güvenli bir sınır koy veya işe yarayan destek iste."},result:{question:"Sana uygun en küçük adımı yaptın mı?",observationPrompt:"Ne yazdın veya sordun, hangi karar hâlâ verilmedi?"},judgment:{primary:{id:"stoic-1-decision",scenario:"Kerem’in öğle molasından sonra on dakikası var. Acil yanıt vermesi gerekmiyor. Başvurusunun girişi açık, ama işe alım sorumlusu projede yaptığı işe dair somut bilgi istemiş. Anlatabileceği uygun bir örnek var.",question:"Bu zamanı nasıl kullansın?",options:[{id:"keep-checking",text:"Olası işverene hemen yanıt verebilmek için birkaç dakikada bir gelen kutusunu kontrol etmeye devam etsin.",feedback:"Ulaşılabilir olmak gerekebilir. Burada acil yanıt beklenmiyor ve yazabileceği yararlı bir örnek var. Gelen kutusuna bakacağı saati seçip bu cümleyi yazmaya zaman ayırsın."},{id:"write-evidence",text:"İlgili proje cümlesini şimdi yazsın, sonra kendi seçtiği saatte gelen kutusunu yeniden kontrol etsin.",feedback:"Bu seçim, iş teklifi vaat etmeden yapılabilir bir işe zaman ayırıyor. Cümleyi kaydet, gerekli iletişim yollarını açık tut. Sonradan gelecek yanıtı yeni bilgi olarak değerlendir."},{id:"revise-opening",text:"Projesini daha açık sunmak için elindeki on dakikayı başvurunun giriş paragrafını yeniden yazmaya ayırsın.",feedback:"Giriş anlaşılmıyorsa düzeltmek işe yarar. Burada giriş zaten açık; eksik olan somut proje bilgisi. Onu şimdi yaz. Sonraki geri bildirim bunu gerektirirse girişe yeniden bak."}],bestOptionId:"write-evidence"}},carry:{takeaway:"Sonucu önemseyebilirsin. Senin yapabileceğin işe de zaman ayır ve gerçekten dene.",followUp:{questionId:"stoic-1-return",question:"Hangi yararlı işi yaptın veya talebi ilettin? Destekle ilgili hangi engel sürdü?",observationPrompt:"Yaptığın işi veya talebi belirt; yapamadıysan hangi koşulun eksik kaldığını yaz.",adjustmentPrompt:"Sıradaki denemeye hangi destek veya başlama anı uyuyor?"}},goDeeper:{sections:[{heading:"Çabanı yönelt, yardımın payını da gör",paragraphs:["Epiktetos’u anlatan akademik kaynak, yargıların, amaçların ve davranışların bize bağlı olduğunu; itibar gibi dış sonuçların ise olmadığını söyler [S09]. Epiktetos Hierapolis’te köle olarak doğdu, daha sonra Nikopolis’te ders verdi. Öğrettiklerini Arrian kaydetti. Bu tarihsel bilgiler geleneği açıklar. Bugün kullanılan bir çalışma kâğıdının etkisini göstermez. Ayrım çabanı yönlendirebilir. Ama bir kişinin dikkatini, duygularını veya davranışını her zaman bütünüyle seçebildiğini kanıtlamaz. Felsefi bir öneriyi psikolojik garanti gibi kullanma.","ODA bu ayrımı, tam kontrol ile çaresizlik arasında yardımın payına da yer vererek uyarlar. Neyi deneyebilirsin? Neyi yardımla etkileyebilirsin? Hangi kararı tek başına veremezsin? Stoic Week el kitabı kontrol ayrımını bir uygulama olarak anlatır [S08]. Bu, tek başına etkisi sınanmış bir deney değil, yol gösteren bir metindir. İşyerindeki sorun ortak hareket etmeyi gerektirebilir. Sağlık sorunu değerlendirme ve sağlık desteği isteyebilir. Zarar veren bir karşılaşmada korunmak gerekebilir. Başkası veya koşullar sonucu etkiliyor diye bunların hiçbiri senin tutumundaki bir kusura dönüşmez."]},{heading:"Yaptığın iş görülebilsin",paragraphs:["Gollwitzer ve Sheeran, 8.461 katılımcılı 94 bağımsız planlama sınamasını birleştirdi [S03]. Belirli bir durumu ve yapılacak davranışı söylemek, hedefe ulaşmayı ortalama olarak artırdı. Hedefler, tasarımlar ve karşılaştırmalar farklıydı. Çalışmalar yalnızca güncel, önceden kaydedilmiş rastgele atamalı deneylerden oluşmuyordu. Standartlaştırılmış etki bir başarı yüzdesi değildir. Çalışma kontrolü ayırma alıştırmasını sınamaz, Stoacılığın etkisini kanıtlamaz. Başlama işaretinin yorgunluğu veya imkân eksikliğini aşacağını da garanti etmez. Bunlar planın uygulanıp uygulanamayacağını hâlâ etkiler.","Bu plan biçimini küçük bir işte kullan: öğle molasından sonra masanda, projede yaptığını anlatan işe yarar bir cümle yaz. Dosyayı açmak hazırlıktır. Mülakat cevabının provası da hazırlıktır; böyle adlandır ve kullanacağın sonraki fırsatı seç. Dışarıdan yanıt gelmesi, adımını tamamlamanın şartı değildir. Yine de gelen geri bildirimi kontrolüm dışında diye gözden çıkarma. Sıradaki planın, öğrendiğin bilgiye, gereken desteğe ve seçtiğin hayat yönüne göre değişsin. Yazdığın cümle ile başvurunun sonucu ayrı şeyler olarak kayıtta kalsın."]}],sourceIds:["stoic-epictetus-iep","stoic-week-handbook","stoic-planning"]}},{schemaVersion:2,revision:2,id:"stoic-2",courseId:"stoic",locale:"tr",title:"Yanıt gelmedi. Sebebini gerçekten biliyor musun?",goal:"Bir yorumunu kanıtlarla kontrol et. Sonra durumu netleştir veya kendini koruyacak bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yanıt gecikti. Bildiklerine göre mi davranıyorsun, yoksa nedenini tahmin mi ediyorsun?",reason:{id:"stoic-2-reason",label:"Henüz doğrulamadığın bu yorum sana ne yaptırdı?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek teslim tarihini netleştirmek","Tahmine göre davranmayı bırakmak","Gereken sınırı korumak"]},why:{id:"stoic-2-why",label:"Henüz doğrulamadığın bu yorum sana ne yaptırdı?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Yanıt gelmemesi bir olgu. “Bana saygı duymuyorlar” ise kanıt gerektirebilecek bir yorum. Bu ayrım, olanların seni incitemeyeceği anlamına gelmez. Seneca öfkeyi anlatırken kendiliğinden gelen ilk tepkiyle sonradan o tepkiyi benimsemeyi ayırıyordu. Bu felsefi bir açıklamaydı. Sıkıntıyı bütünüyle açıklayan bilimsel bir model değildi.","Aynı hedefe ve işe dön. Önüne çıkan bir yorumun lehinde ve aleyhinde ne biliyorsun? Gerçekçi başka bir açıklama “Henüz bilmiyorum” olabilir. Sonra teslim tarihini netleştir, yanlış bilgiyi düzelt veya sınır koy. Gerçekten kötü davranılmış olmasını gözden kaçırma. Daha az üzülmen şart değil; burada denediğin şey bildiklerine uygun davranmak."],example:{title:"Kerem geciken yanıtı soruyor",text:"Salı günü Kerem masasında, referans yazısıyla ilgili iki mesajının yanıtsız kaldığını görüyor. İş arkadaşının yaptığı işi yetersiz bulduğunu düşünüyor. Sebebi doğrulayamıyor, ama teslim tarihi belli. Yazının perşembeye yetişip yetişmeyeceğini soran tek bir mesaj gönderiyor. Akşama kadar yanıt gelmiyor. Kerem gönderdiği soruyu ve hâlâ bilmediği sebebi kaydediyor. Yaptığı işi, karşı tarafın henüz vermediği yanıttan ayırıyor."}},move:{invitation:"Bir yorumuna yeniden bak. Sonra bildiklerine dayanan bir adım at.",instructions:["Olanı ve ona verdiğin anlamı ayrı ayrı belirt.","Durumu netleştir, yanlış bilgiyi düzelt veya güvenli bir sınır koy."],prompts:[],suggestions:{action:["Hedefimle ilgili durumu netleştiren soru gönder","Projede kanıta dayalı bir düzeltme yap","Güvenli bir sınır iste"],minimum:["Teslim tarihini soran açık mesaj gönder","Düzeltilmiş bir cümle yaz","Güvenli ve belirli bir sınır söyle"],cue:["Sıradaki yanıtımı vermeden önce","Sonraki proje görüşmemde","Teslim tarihini netleştirmem gerektiğinde"],place:["Güvenli bir mesajlaşmada","Her zamanki çalışma masamda","Rahatça kullanabildiğim özel bir yerde"],minutes:[2,5],fallback:["Netleştirmek için başka güvenli yol seç","Niyeti tahmin etmeden bildiklerimi kullan","Yeniden iletişim kurmadan önce destek al"],observation:["Sorum ve gerçekten gelen yanıt","Düzelttiğim bilgi","İlettiğim sınır"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Hedefimle ilgili durumu netleştiren soru gönder",minimum:"Teslim tarihini soran açık mesaj gönder",minutes:2,cueHint:"Sıradaki yanıtımı vermeden önce",placeHint:"Güvenli bir mesajlaşmada",obstacleHint:"İletişim güvenli değil veya karşı taraf yanıt vermiyor.",fallbackHint:"Netleştirmek için başka güvenli yol seç",observationHint:"Sorum ve gerçekten gelen yanıt"},stopRule:"Gerçek zarar varsa korunmak gerekir. Kötü davranıldığına dair kanıtın yerine rahatlatıcı bir tahmin koyma.",accessibleAlternative:"Alıştığın yolla veya güvenli bir yazılı mesajla yanıt ver. İletişim kurmak yerine destek de alabilirsin."},result:{question:"Bildiklerine dayanan yanıtını kullandın mı?",observationPrompt:"Gerçekte ne söyledin? Karşı taraftan nasıl bir yanıt geldi?"},judgment:{primary:{id:"stoic-2-decision",scenario:"İş arkadaşı, söz verdiği referans yazısı hakkında iki kez yanıt vermedi. Kerem’in yazıya perşembe ihtiyacı var. Gecikmenin sebebiyle ilgili elinde kanıt yok.",question:"Hangi yanıt hem yorumu kontrol eder hem tarihle ilgilenir?",options:[{id:"comfort-guess",text:"İş arkadaşının çok yoğun olduğunu varsaysın ve ilişkiyi germemek için herhangi bir mesaj göndermeden beklesin.",feedback:"Yoğunluk mümkün, ama henüz doğrulanmış bir açıklama değil. Verilen sözler ve yaklaşan tarih, bildiklerine dayanan bir soru gerektiriyor. İş arkadaşının niyeti hâlâ bilinmeyebilir; yine de tarihi sorabilir."},{id:"withdraw-work",text:"Eksik yanıtların etkisini iş arkadaşına göstermek için şimdilik birlikte yaptığı işlerdeki yardımını biraz azaltsın.",feedback:"Sınır koymak gerekebilir. Ama sebebi bilmeden işbirliğini azaltmak yeni bir varsayım ekler. Uygun sınırı seçmeden önce teslim tarihini ve gecikmeye neyin yol açtığını netleştirsin."},{id:"clarify-deadline",text:"Yanıtsız mesajları belirtip perşembenin uygun olup olmadığını veya başka bir yol gerekip gerekmediğini sorsun.",feedback:"Bu seçim, gerçek bir örüntüyü gözden kaçırmadan eksik bilgiyi soruyor. Tarafsız açıklama, zorla olumlu düşünmek değildir. Sessizlik dahil sonucu kaydet. Sonraki destek veya sınır ihtiyacını buna göre seç."}],bestOptionId:"clarify-deadline"}},carry:{takeaway:"Yorumunu kanıtla kontrol et, gerçekten olanla ilgilen. Rahatlatan bir tahmin de hâlâ tahmindir.",followUp:{questionId:"stoic-2-return",question:"Yeni kanıt yorumunu destekledi mi, değiştirdi mi? Sebep belirsiz mi kaldı, yoksa zarar mı ortaya çıktı?",observationPrompt:"Hangi kanıt değişti? Karşı tarafın niyetini hâlâ bilmiyor musun?",adjustmentPrompt:"Yeniden netleştirmek, planı değiştirmek veya destek almak mı gerekiyor?"}},goDeeper:{sections:[{heading:"İlk tepki başka, yorumu kontrol etmek başka",paragraphs:["Seneca öfkeyi anlatırken istemeden gelen ilk hareketlerle, öfkenin bütünüyle oluşmasında yer alan benimsemeyi ayırır [S10]. Bu tarihsel bir felsefi ayrımdır. Duyguları bütünüyle açıklayan deneysel bir model değildir. Panik, ağrı, travma belirtileri veya kendiliğinden beliren bir düşünce, yanlış seçim yaptığını göstermez. Gerçek olay, içinde bulunduğun koşullar ve yorumların birlikte önem taşıyabilir. Bir yoruma bakmak, kullanışlı bir bakış açısıdır. Birinin neden sıkıntı çektiğinin tek açıklaması değildir. İlk duyguyu bastırmak veya yanlış bulmak zorunda değilsin.","NHS düşünce kaydında yedi soru sunar: durum, duygular, düşünce, destekleyen kanıt, karşı kanıt, gerçekçi alternatif ve sonrasındaki duygular [S11]. Her iki taraftaki kanıt önemlidir. Alternatif yorum rahatlatıcı olmak zorunda değil; tarafsız olabilir. Örnekte “Söz verilen tarih geçti ve sebebini bilmiyorum” hem sorunu hem belirsizliği korur. ODA’nın kısa kontrolü ve sonraki adımı bu rehberi sadeleştirir. Terapi sunmaz veya sonraki duyguların daha iyi olmasını gerektirmez. Sorduğun soruyu ve gerçekte gelen yanıtı ayrı kaydetmen, tahminin değişip değişmediğine bakmanı sağlar."]},{heading:"Tedaviye benzemek, aynı etkiyi vermek değildir",paragraphs:["Hofmann ve çalışma arkadaşları bilişsel davranışçı terapiyi, yani BDT’yi derlerken 269 meta-analiz buldu. Bunların temsili 106’sını ele aldı [S01]. Derleme özellikle bazı kaygı sorunları, öfke ve genel stres için soruna özgü güçlü kanıtlar anlattı. Bütün BDT için tek bir birleşik etki veya katılımcı sayısı vermedi. Bu bulgular araştırılan tedavilere aittir. Tedavideki bir fikre benzeyen her alıştırmaya aktarılamaz. Felsefe dersi okumak klinik BDT almak değildir; benzer bir ayrımı kullanmak da tedavinin tamamını sunmaz.","Düşünce kaydı resmî bir kişisel destek rehberinde anlatılır [S11]. Fakat o kaynak kaydın tek başına klinik etki büyüklüğünü belirlemez. Kanıtı yorumdan ayırmak ve uygun yanıtı seçmek için kullanabilirsin. Geciken her mesajı düşünce hatası sayma, istismarı zararsız diye yeniden yorumlama. Sıkıntı ağırsa, sürüyorsa veya günlük işlerini etkiliyorsa uzman desteği uygun adım olabilir. Kaydında değişmeyen öfke, durumu netleştiren bir soru veya kendini koruyan bir seçim yer alabilir. Bunların hiçbirini dersin başarısızlığı gibi değerlendirmek zorunda değilsin."]}],sourceIds:["stoic-seneca-iep","stoic-thought-record","stoic-cbt"]}},{schemaVersion:2,revision:2,id:"stoic-3",courseId:"stoic",locale:"tr",title:"İşin yine bölündü. Sonra ne yapacaksın?",goal:"Karşılaştığın engelde ne yapabileceğini seç. Aynı yararlı işi yapmanı destekleyecek bir yol olsun.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Planın her şey yolundayken işliyor. Alıştığın kesinti geldiğinde ne yapacaksın?",reason:{id:"stoic-3-reason",label:"Bu kez hangi gerçek engel için bir yol gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Her zamanki kesintiden sonra işe dönmek","Kısa çalışma zamanını korumak","Erişim için yardım istemek"]},why:{id:"stoic-3-why",label:"Bu kez hangi gerçek engel için bir yol gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ters gidecek şeyleri hayal etmekle ne yapacağını planlamak farklıdır. Planlama araştırmaları belirli bir engeli veya fırsatı yapılabilir bir işle eşleştirir. Canlı olumsuz sahneler hayal etmenin seni dayanıklı kıldığını göstermez. Burada işe yarayacak şey daha kötü bir sahne değil, gerektiğinde kullanabileceğin bir yoldur.","Aynı hedefi ve işi koru. Kaydından gündelik, gerçekçi bir engel seç. “Şu olursa bunu yaparım” diye planla, gerekirse kullan. Hayalinde canlandırmak isteğe bağlı. Felaketi veya travmayı yeniden yaşama. Engel hiç çıkmazsa bu yanıt için “Fırsat olmadı” seç. O sırada normal işini yapmayı denediysen onu ayrıca kaydet; yedek yolu kullanmış sayma."],example:{title:"Kerem aramadan sonra dönüyor",text:"Çarşamba portföyüne çalışacağı öğle molasından önce Kerem, sık gelen arama için plan yapıyor. Arama bitince işe yarar bir proje cümlesiyle başlayacak. Masasındayken arama geliyor. Bitince dönüyor, cümleyi sesle yazdırıp kaydediyor. O öğleden sonra daha fazlasını yapamıyor. Yine de o gün gerçekten kullandığı yolu kaydediyor: aramayı cevapladı, sonra cümlesine döndü. Yalnızca hazırladığı planı yapmış saymıyor."}},move:{invitation:"Aynı işte karşılaştığın engel için kullanabileceğin bir yol hazırla.",instructions:["Gözünde canlı sahneler kurmadan olası bir engeli belirt.","Gerekirse seçtiğin yolu kullan; sonra gerçekte ne olduğunu kaydet."],prompts:[],suggestions:{action:["Kesinti olursa seçtiğim yolla işe dön","Proje için uygulanabilir bir sınır iste","Gerekirse erişim desteğimi kullan"],minimum:["Kullanabileceğim bir proje cümlesi yaz","Belirli bir sınır talebi ilet","Belirli bir erişim talebi ilet"],cue:["Her zamanki kesinti bittiğinde","Koruduğum çalışma zamanından önce","Erişim engeli ortaya çıktığında"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["İşe yarayan cümleyi sesle yazdır","Sonraki uygun çalışma fırsatını seç","Güvendiğim birinden yardım iste"],observation:["Kesinti oldu mu, işe döndüm mü","Seçtiğim yolu kullanıp kullanmadığım","Yazdığım işe yarar cümle"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Kesinti olursa seçtiğim yolla işe dön",minimum:"Kullanabileceğim bir proje cümlesi yaz",minutes:2,cueHint:"Her zamanki kesinti bittiğinde",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Seçtiğim yol, bende olmayan zaman veya erişim gerektiriyor.",fallbackHint:"İşe yarayan cümleyi sesle yazdır",observationHint:"Kesinti oldu mu, işe döndüm mü"},stopRule:"İstersen gözlerini açık tut. Panik, kendinden veya çevrenden kopma hissi ya da istemsiz anılar gelirse dur veya atla.",accessibleAlternative:"Canlandırmadan planla. Daha küçük bir iş, işe yarayan destek veya güvenli bir ara seç."},result:{question:"Gerektiğinde seçtiğin yolu gerçekten kullandın mı?",observationPrompt:"Beklediğin engel ortaya çıktı mı? O anda gerçekte ne yaptın?"},judgment:{primary:{id:"stoic-3-decision",scenario:"Kerem’in öğle portföy çalışması, cevaplaması gereken kısa bir aramayla sık bölünüyor. Öncesindeki zamanı bakım sorumluluğu dolduruyor. Arama sonrasında genellikle iki dakika kalıyor. Proje cümlesi bu akşam lazım.",question:"Bu öngörülebilir engele hangi yol uyuyor?",options:[{id:"restart-small",text:"Cevaplaması gereken aramayı alsın, bittikten sonra kalan zamanda işe yarar bir proje cümlesi yazsın.",feedback:"Bu seçim gerekli aramayı ve kalan zamanı hesaba katıyor. Seçtiği yol yapılabilir ve kaydedilebilir. Engel çıktı mı, sonrasında gerçekten işe döndü mü, bunu ayrı ayrı kaydetsin."},{id:"same-minimum-tomorrow",text:"Aramadan sonra öğle molasını boş bıraksın; aynı cümleyi yazmak için yarınki iki dakikalık zamanı kullansın.",feedback:"Zaman veya güç yetmiyorsa aynı küçük işi başka zamana almak dinlenmeyi koruyabilir. Burada iki dakika var ve cümle bu akşam lazım. Şimdi dene; gücün değişirse uyarla."},{id:"move-before-lunch",text:"Portföy çalışmasını öğle molasının öncesine alsın ve gerekli aramayı da o sırada cevaplayacak biçimde ayarlasın.",feedback:"Öncesi boş olsaydı zamanı değiştirmek kesintiyi önleyebilirdi. Ama orada bakım sorumluluğu var. Gerekli aramayı cevapla, sonra öğle molasında kalan zamanı işe yarar bir cümle için dene."}],bestOptionId:"restart-small"}},carry:{takeaway:"Gerektiğinde kullanabileceğin bir yol hazırla. Felaket sahnesini tekrar tekrar oynatman gerekmiyor.",followUp:{questionId:"stoic-3-return",question:"Beklediğin engel çıktı mı? Seçtiğin yolu o koşullarda kullanabildin mi?",observationPrompt:"Engeli, işe dönmek için kalan zamanı ve kullandığın yolu belirt. O yolu denemediysen bunu da yaz.",adjustmentPrompt:"Aynı yolu korumak, küçültmek veya ortamı değiştirmek mi gerekiyor?"}},goDeeper:{sections:[{heading:"Eski zorluk alıştırması, güncel planlama",paragraphs:["Stoic Week el kitabı zorluklar üzerine düşünmeyi bir uygulama olarak anlatır [S08]. Bu uygulayıcı rehberi, olumsuz canlandırmanın tek başına etkisini göstermez. Verdiği açıklama kanıtlanmış bir mekanizma gibi sunulamaz. Kendi başına maruz bırakma tedavisi yapma izni de değildir. ODA bunun yerine gündelik, hafif bir engel; isteğe bağlı canlandırma ve yapılabilir bir yol sunar. Bunlar uyarlamadır. Seni üzen bir anıya dönmeden, yalnızca sözcüklerle plan yapabilirsin. Engelini açıkça belirtmek için sahneyi gözünde canlandırman veya onun ne kadar kötü olabileceğini büyütmen gerekmiyor.","“Şu olursa bunu yaparım” planları, belirli bir durumu yapmak istediğin davranışla eşleştirir [S03]. Bu planları tek başına inceleyen araştırmalar da vardır. 2006 derlemesi 8.461 katılımcılı 94 bağımsız sınamayı içerdi ve farklı koşullarda hedefe ulaşmada ortalama faydalar buldu. Plan yazmanın yorgunluğu, engelliliği veya eksik imkânları aşacağını göstermedi. Seçtiğin yol daha küçük yararlı bir iş, sınır veya destek olabilir. Engel tehlikeyse nasıl dayanacağını değil, güvenliğini ele al. Canlandırma panik, dissosiyasyon yani kendinden veya çevrenden kopma hissi, ya da istemsiz anılar getirirse dur. Canlandırmasız plan seçeneği hâlâ açık."]},{heading:"Her engel senin içinde değildir",paragraphs:["Wang ve çalışma arkadaşları zihinsel karşılaştırmayla “şu olursa bunu yaparım” planlarını birleştiren yöntemi derledi [S04]. Sıra; yapılabilir istek, istenen sonuç, mevcut engel ve o durumda yapılacak davranıştır. 21 makalede 15.907 katılımcılı 24 bağımsız tahminde, hedefe ulaşma ortalama olarak mütevazı biçimde arttı: g = 0,336. Çalışmalar ve sunum biçimleri farklıydı. Çalışmalar arası ciddi farklılık ve değişen kalite vardı. Bulgular iki dakikanın en iyi süre olduğunu, olumsuz sahnenin tek başına etkisini veya bu ODA biçimini doğrulamıyor. Sonucu farklı bir alıştırmaya taşımak doğru olmaz.","Gerekli arama, olmayan ulaşım, bakım sorumluluğu veya kullanamadığın araç gerçek bir koşuldur. Yalnızca düşünce biçiminle ilgili bir sorun değildir. Doğru adlandır. Yardım isteyebilir, fırsatı değiştirebilir veya uygun olmayan planı bırakabilirsin. Birkaç yeni ritüel eklemek yerine tek bir koşulu sına. Hazırlığı ve kullanımı ayır: işe dönme planını yazmak geri döndüğünü göstermez. Kesinti çıkmazsa yedek yolu sınamamış olursun. Bu belirsizliği koru; o gün yaptığın normal işi de kendi koşullarıyla kaydet. Böylece sonraki plan, hayal ettiğin bir başarıya değil, gerçekte ne yaptığına dayanır."]}],sourceIds:["stoic-week-handbook","stoic-planning","stoic-mcii"]}},{schemaVersion:2,revision:2,id:"stoic-4",courseId:"stoic",locale:"tr",title:"Sert cevabın hazır. Peki işine yarayacak mı?",goal:"İstersen kendi adınla düşün. Sonra hedefin için bildiklerine dayanan bir yanıt kullan.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"Vereceğin sert yanıt hazır. On saniye geçtikten sonra hedefin için hangi yanıt işe yarayacak?",reason:{id:"stoic-4-reason",label:"Gerçeğe dayanan bir yanıt neyi korur veya ilerletir?",kind:"text",maxLength:160,optional:!0,suggestions:["İşe yarayan işbirliğini korumak","Yanlış bilgiyi düzeltmek","Açık bir sınırı korumak"]},why:{id:"stoic-4-why",label:"Gerçeğe dayanan bir yanıt neyi korur veya ilerletir?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kısa süre düşünürken kendi adını kullanmak, duruma biraz mesafeden bakmanı sağlayabilir. Deneyler bunu inceledi; daha geniş kanıtlarda ise etkiler mütevazı ve değişken. Sakinleşme garantisi yok. Uzaydan dünyaya bakmak veya on yıl sonrasını düşünmek başka alıştırmalar. Buradaki kaynaklar onların belirli bir faydasını göstermiyor.","Gergin bir an hedefinin önüne geçtiğinde bu aracı deneyebilirsin. İsteğe bağlı 60 saniyelik hazırlık: “Kerem, hangi bilgi yanlış? Hangi talep işe yarar?” Kendi adını koy veya atla. Ardından bildiklerine dayanan bir cümle, talep veya sınır kullan. Mesafe almak, zararı silmek değildir. Öfken sürse de kullandığın yanıtı kaydet; düşündüğünü değil, söylediğini belirt."],example:{title:"Kerem olanı netleştiriyor",text:"Perşembe günü güvenli bir proje görüşmesinde Kerem, kontrol listesinin gecikmeye yol açtığını duyuyor. Sert yanıt vermek istiyor. Kendi adını kullanarak işin ilerlemesine neyin yardım edeceğini soruyor. Sonra gerçek devir tarihini söyleyip hangi adımın değişmesi gerektiğini soruyor. İş arkadaşı hâlâ kızgın. Kerem anlaşmazlığı çözdüğünü iddia etmiyor; o gün gerçekten söylediği cümleyi ve ilettiği talebi kaydediyor."}},move:{invitation:"İşe yarıyorsa biraz mesafe al. Sonra bildiklerine dayanan bir iş yap.",instructions:["İstersen kendi adınla 60 saniye düşün. Bu hazırlıktır.","Gerçeğe dayanan bir cümle, talep veya güvenli bir sınır kullan."],prompts:[],suggestions:{action:["Bir yanlış bilgiyi düzelt ve talep ilet","Proje için açık bir sınır söyle","Bildiklerime dayanan bir açıklama sorusu sor"],minimum:["Gerçeğe dayanan bir cümle kullan","Güvenli ve belirli bir sınır söyle","Açık bir soru gönder"],cue:["Sıradaki gergin yanıtımdan önce","Yanlış suçlama tekrarlandığında","Sonraki güvenli proje görüşmemde"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Güvenli görüşme yerinde"],minutes:[2,5],fallback:["Güvenli yazılı yanıtta olanı belirt","İletişime ara ver ve destek al","Başka güvenli bir fırsat seç"],observation:["Gerçekte kullandığım cümle","Talebim ve gerçekten gelen yanıt","Sınırı korumak için hâlâ destek gerekiyor mu"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Bir yanlış bilgiyi düzelt ve talep ilet",minimum:"Gerçeğe dayanan bir cümle kullan",minutes:2,cueHint:"Sıradaki gergin yanıtımdan önce",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Karşılaşma güvenli değil veya bu ara sıkıntımı artırıyor.",fallbackHint:"Güvenli yazılı yanıtta olanı belirt",observationHint:"Gerçekte kullandığım cümle"},stopRule:"Gündelik bir durum seç. Panik, kendinden veya çevrenden kopma hissi ya da istemsiz anılar gelirse dur veya atla.",accessibleAlternative:"Gözlerini açık tutabilir, düşünme adımını atlayabilir, yanıtını yardımla verebilir veya destek alabilirsin."},result:{question:"Seçtiğin, gerçeğe dayanan yanıtı kullandın mı?",observationPrompt:"Ne söyledin veya hangi sınırı koydun? Sonra ne oldu?"},judgment:{primary:{id:"stoic-4-decision",scenario:"Güvenli bir görüşmede Kerem yine haksız yere suçlanıyor. Yanlış tarih, sıradaki iş devrini geciktiriyor; Kerem gerçek tarihi biliyor. Kısa bir aradan sonra işi ilerletmek ve bilgiyi düzeltmek istiyor.",question:"Hangi yanıt mesafe alırken sorundan kaçınmaz?",options:[{id:"let-pass",text:"Ekip bu anlaşmazlık yerine işi yetiştirmeye odaklanabilsin diye suçlamayı şu an yanıtsız bırakıp görüşmeyi sürdürsün.",feedback:"İşi ilerletmek önemli. Ama sessiz kalmak, iş için gerekli yanlış bilgiyi düzeltmeden bırakır. Devir tarihini söylesin, sıradaki adım için talep iletsin. Gerekirse sınır da koyabilir."},{id:"facts-request",text:"İşin devir tarihini söylesin, neyin değişmesi gerektiğini sorsun; suçlama sürerse buna açık bir sınır koysun.",feedback:"Bu seçim, kısa düşünme adımından sonra yararlı bir işe geçiyor. Doğru bilgiyi söylemek ve talep iletmek, sakinlik şartı koymadan işi korur. Örüntü sürerse sınır koyma seçeneği de açık kalır."},{id:"separate-follow-up",text:"Tekrarlayan suçlama için ayrı bir görüşme istesin, ama şu anki konuşmayı yanlış tarihi düzeltmeden sürdürsün.",feedback:"Ayrı görüşme tekrarlayan örüntüyü ele alabilir. Burada yanlış tarih şu anki işi de etkiliyor. Kısaca şimdi düzelt, daha geniş konuşma gerekiyorsa sonra ayrıca zaman ayarla."}],bestOptionId:"facts-request"}},carry:{takeaway:"Verdiğin kısa ara, işe yarayan bir yanıt seçmene yardım ettiğinde anlam kazanır.",followUp:{questionId:"stoic-4-return",question:"Kendi adınla düşünmek yardım etti mi, önüne mi geçti, yoksa gereksiz mi geldi?",observationPrompt:"Hangi aracı kullandın veya atladın? Ardından gerçeğe dayanan hangi yanıtı verdin?",adjustmentPrompt:"Aracı korumak, bırakmak veya desteği güçlendirmek mi gerekiyor?"}},goDeeper:{sections:[{heading:"Kendi adınla düşünme deneyinde ne yapıldı?",paragraphs:["Kross ve çalışma arkadaşları, 585 katılımcılı yedi çalışma bildirdi [S05]. 1a çalışmasındaki 56 üniversite öğrencisi, yakın zamanda yaşadıkları üzücü bir olayın nedenini 60 saniye düşündü. Birinci kişi yerine kendi adlarını ve birinci kişi dışındaki zamirleri kullandılar. Katılımcılar daha fazla mesafe aldıklarını bildirdi. Sonraki deneyler stresli sosyal görevleri ve performansı inceledi. Bunlar tek araştırma programında birbirini destekleyen deneylerdir. Yedi bağımsız klinik rastgele atamalı deney veya kendi adını kullanmanın kaygıyı tedavi ettiğinin kanıtı değildir. Bulguyu araştırılan düşünme biçimiyle sınırlı tutmak gerekir.","Bu ders, olayı hafif ve güncel bir durumla değiştirip sonrasına gerçeğe dayanan bir adım ekliyor. Bu ODA uyarlaması, özgün protokol değil. Acı veren bir anıyı bulmak, gözlerini kapatmak veya kendini uzaydan görmek zorunda değilsin. Cümle tuhaf geliyorsa ya da seni sarsıyorsa atla. İşi ilerletmek için ne gerektiğini doğrudan sorabilir, güvenli bir yazılı yanıt kullanabilir veya destek arayabilirsin. O anda yanıt vermek ayrı bir iştir. Düşünmek veya taslak yazmak tek başına hazırlık olarak kalır; mesajı kullandığın anı ayrıca kaydet."]},{heading:"Mütevazı etkiler, uyku vaadi yok",paragraphs:["Murdoch ve çalışma arkadaşları 17 makalede 2.397 yetişkinle yapılan 25 deneyi birleştirdi [S06]. Mesafeden düşünmenin genel etkisi mütevazıydı: g = 0,19, %95 güven aralığı 0,05 ile 0,33. Kanıt kalitesi belirsizdi. Katılımcılar çoğunlukla genç ve görünürde sağlıklıydı; sonuçlar ciddi ölçüde farklıydı. Tahmin aralığı sıfırı kapsıyordu. Dört deneyde nesnel sonuçlarda istatistiksel olarak anlamlı fark bulunmadı. Bunlar daha ağır sıkıntı yaşayanlarda üstün fayda veya uzaydan dünyaya bakma ya da on yıl sonrasını düşünme alıştırmalarının belirli etkisini göstermez. Birleşik ortalama, herkesin aynı sonucu alacağını söylemez.","Önceden kaydedilmiş bir düşünme çalışması, mesafe almayı uykuya yönelik bir müdahale olarak desteklemedi [S16]. Uyku kalitesindeki değişim olaya kendi gözünden bakan grubu destekledi. Uyku süresinde istatistiksel olarak anlamlı fark bulunmadı. Bir gruptan daha çok katılımcının çıkarılması yorumu zorlaştırdı. İyi oluş tablosuyla anlatımdaki işaretler çeliştiği için iyi oluşun hangi yönde değiştiği söylenemez. Bu aracı daha iyi uyku veya güvenilir rahatlama için değil, istersen bakış açını değiştirmek için seç. Konunun ciddiyetini koru. Gerçeğe dayanan bir adım atmana yardım edip etmediğine bak."]}],sourceIds:["stoic-kross-self-talk","stoic-kross-distancing","stoic-distancing-sleep"]}},{schemaVersion:2,revision:2,id:"stoic-5",courseId:"stoic",locale:"tr",title:"Kötü geçen bir deneme bütün karakterini anlatmaz.",goal:"Son denemene adilce bak. Seçtiğin somut düzeltmeyi sıradaki fırsatta kullan.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Neyin ters gittiğini hâlâ başa mı sarıyorsun? Sıradaki denemede kullanabileceğin tek bir değişiklik bul.",reason:{id:"stoic-5-reason",label:"Tekrar düşünüp durmak yerine hangi somut koşulu değiştirmek gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerçek denemeden öğrenmek","İşe yarayan bir düzeltme yapmak","Bütün karakterimi yargılamayı bırakmak"]},why:{id:"stoic-5-why",label:"Tekrar düşünüp durmak yerine hangi somut koşulu değiştirmek gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Stoacı el kitabının akşam değerlendirmesi, neyin ters gittiğini, neyin iyi gittiğini ve neyin değişebileceğini sorar. Bu anlatılmış bir yöntemdir. Bağımsız biçimde kanıtlanmış tedavi veya uyku yardımı değildir. Somut olana bak. “Kararlaştırdığımız tarihi kaçırdım” düzeltilecek bir şey verir. “Ben işe yaramam” ise sonraki adımı göstermez.","Aynı denemenin son kaydını kullan. Amacına yarayan bir kısmı koru, yaramayan tek bir koşulu değiştir. Sonra bu düzeltmeyi sıradaki işte kullan. Değerlendirme öğrenme veya hazırlıktır; sonraki işi yaptığın anlamına gelmez. Ertesi gün dönüşün yeterliyse ayrı bir gece ritüeli ekleme. Bu kontrol, gerçekte ne yapacağına yol göstersin."],example:{title:"Kerem değerlendirmeyi kullanıyor",text:"Cuma öğle molasında Kerem masasında, perşembe görüşmesini yeniden değerlendiriyor. Tarihi düzeltti ama dayanak olan notu eklemedi. Tarihi düzeltmesini olumlu bir adım sayıyor. Tek değişiklik seçiyor: sonraki mesajına bunu destekleyen cümleyi eklemek. O öğleden sonra mesajı gönderiyor. Anlaşmazlık sürüyor. Kaydında olayı değerlendirmekle düzeltilmiş mesajı gerçekten göndermek ayrı duruyor. İlkini bitirmesi, ikincisini de yaptığı anlamına gelmiyor."}},move:{invitation:"Son kaydına bak. Bir düzeltme seç ve dene.",instructions:["İşe yarayan bir kısmı ve uymayan somut bir koşulu belirt.","Seçtiğin düzeltmeyi sıradaki işte kullan."],prompts:[],suggestions:{action:["Değerlendirme sonunda seçtiğim proje düzeltmesini uygula","Kaydıma uygun bir telafi yap","Yararlı işimi yeni başlama anında yap"],minimum:["Düzeltilmiş bir proje cümlesi gönder","Belirli bir telafi talebi ilet","Kullanabileceğim bir proje cümlesi yaz"],cue:["Sonraki proje mesajımda","Sonraki güvenli telafi fırsatında","Seçtiğim yeni başlama anında"],place:["Güvenli bir mesajlaşmada","Her zamanki çalışma masamda","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["Yanlış bilgiyi daha kısa düzelt","Başka güvenli bir fırsat seç","Başa sarmak yerine destek al"],observation:["Gerçekten uyguladığım düzeltme","Bu değişiklikle ne yapabildiğim","Talebim ve gerçekten gelen yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Değerlendirme sonunda seçtiğim proje düzeltmesini uygula",minimum:"Düzeltilmiş bir proje cümlesi gönder",minutes:2,cueHint:"Sonraki proje mesajımda",placeHint:"Güvenli bir mesajlaşmada",obstacleHint:"Değerlendirme tekrara dönüyor veya düzeltme güvenli değil.",fallbackHint:"Yanlış bilgiyi daha kısa düzelt",observationHint:"Gerçekten uyguladığım düzeltme"},stopRule:"Düşünceleri tekrar tekrar döndüren veya uykunu bozan değerlendirmeyi bırak, kısalt ya da başka zamana al. Güvenliğini koru.",accessibleAlternative:"Kısaca konuşarak veya yardımla değerlendir. Yeni ritüel yerine kayıtlı dönüşünü ya da desteği kullan."},result:{question:"Seçtiğin somut düzeltmeyi sıradaki işinde kullandın mı?",observationPrompt:"Gerçekte yaptığın işte hangi kısmı değiştirdin?"},judgment:{primary:{id:"stoic-5-decision",scenario:"Bakım sorumluluğu geç bittiğinde Kerem’in akşam çalışma zamanı iki kez aksadı. Hâlâ projesini somut biçimde anlatmak istiyor. Öğle molasında masasında kullanabileceği güvenli iki dakika var.",question:"Değerlendirmeyi ne işe yarar hale getirir?",options:[{id:"same-plan",text:"Bakım işinin geç bitmesini kaydetsin; daha düzenli olabilmek için aynı akşam zamanını yeniden denesin.",feedback:"Kayıt dürüst, ama aynı koşul tekrar tekrar işlemedi. Hedefi koru. Aynı zamanın yeniden işlemesini beklemek yerine öğle molasında yapılabilen en küçük işi sına; ne olduğuna bak."},{id:"make-up",text:"Kaçırdığı zamanı kaydetsin ve eksik işi telafi etmek için hafta sonuna daha uzun bir çalışma koysun.",feedback:"Daha uzun çalışma yapılabiliyorsa yararlı olabilir. Ama tekrarlayan başlama anı sorununu sınamaz. Telafi yükü eklemeden önce, mevcut kısa zamanı kullan. Sonraki planını gerçekten olanlara göre değiştir."},{id:"cue-change",text:"Üstlendiği bakım sorumluluğunu hesaba katsın ve tek proje cümlesini elindeki öğle molası zamanına taşısın.",feedback:"Bu seçim gerçek kısıtı adlandırıyor, yapılanı koruyor ve tek koşulu değiştiriyor. Değerlendirme sıradaki denemeden ayrı. Öğle molasında işin gerçekten yapılıp yapılmadığını ayrıca kaydet; planı uygulama sayma."}],bestOptionId:"cue-change"}},carry:{takeaway:"Denemene adilce bak, tek bir koşulu değiştir. Sonra bu değişikliği sıradaki gerçek işte dene.",followUp:{questionId:"stoic-5-return",question:"Değiştirdiğin koşulu sınadın mı? Bu değişiklikle ne yapabildin?",observationPrompt:"Düzeltmeyi ve yaptığın işi belirt; koşul sınanmadıysa bunu da açıkça söyle.",adjustmentPrompt:"Düzeltmeyi korumak, başlama anını değiştirmek veya destek almak mı gerekiyor?"}},goDeeper:{sections:[{heading:"Değerlendirme yol gösterir, hüküm vermez",paragraphs:["Stoic Week el kitabı, yatağa girmeden önce beş ile on dakikalık akşam değerlendirmesini anlatır [S08]. Üç soru neyin ters gittiğini, neyin iyi gittiğini ve neyin farklı olabileceğini sorar. Kendine bir arkadaşını değerlendireceğin kadar adil bakmanı önerir. Bu, anlatılmış bir uygulayıcı yöntemidir. Deneyle belirlenmiş en iyi süre veya değerlendirmenin tek başına sınandığı çalışma değildir. ODA dönüşünü kısaltmak ve değerlendirmeyi erkene almak uyarlamadır. El kitabındaki süre, herkesin her akşam yerine getirmek zorunda olduğu bir şart olarak alınmamalı.","Bütün karakterini yargılamak yerine seçtiğin denemeye bak. Gözlenebilen bir aksama, işe yarayan bir katkı ve somut bir değişiklik belirle. Affetmeyi, özrü veya sıcak bir duyguyu şart koşma. Zarar verdiğinde telafi uygun olabilir; sana zarar verildiğinde korunmak uygun olabilir. Değerlendirme cezaya, tekrara veya uyku sorununa dönüyorsa kısalt, başka zamana al ya da bırak. Burada amaç, uygulayabileceğin bir düzeltme bulmak. Rahatlamayı garanti etmek veya fazladan bir gece görevi eklemek değil. Sonraki kaydın bu düzeltmeyi gerçekten kullanıp kullanmadığını gösterebilir."]},{heading:"Stoacı eğitim araştırmaları var, sınırları da var",paragraphs:["Stoacı eğitim üzerine doğrudan kontrollü araştırmalar henüz başlangıç aşamasında. Maclellan ve Derakshan, çok kaygılanan 45 kişiyi sekiz oturumluk Stoacı eğitim, birleşik eğitim ve aktif kontrol gruplarına rastgele ayırdı [S13]. Özetleri tekrarlayan düşüncelerde ve kişinin yapabileceğine inancında değişimler bildirdi. Hangi parçanın yardımcı olduğunu veya akşam değerlendirmesinin tek başına tanı konmuş kaygıyı tedavi ettiğini göstermez. Küçük bir eğitim çalışması, bu değerlendirmeyi tekrar etmenin belirtilerini güvenilir biçimde değiştireceğini söyleyemez. Eğitim paketini burada kullandığın kısa alıştırmayla aynı saymamak gerekir.","King’in 2025 doktora tezinde klinik örneklem dışındaki 119 yetişkin, iki haftalık çevrim içi Stoacı eğitime veya bekleme listesine ayrıldı [S15]. Kurum özeti, bütün ölçümleri bulunan kişilerde bazı ruh sağlığı ölçümlerinde olumlu değişimler bildirdi. Bekleme listeli, yayımlanmamış tez erken kanıt sağlar; hakemli araştırmaların ortak sonucu değildir. İki çalışma da bu kısa ODA uyarlamasının eğitimi tekrarladığını göstermez. Sana uyuyorsa adil bir düzeltme dene ve olanı kaydet. Sıkıntı sürüyorsa veya günlük işlerini etkiliyorsa uzman desteği al. Kayıt gerçekten değişen koşulu ve denenen işi belirtmeli. Yeni plan tek başına düzeltmeyi sınamaz."]}],sourceIds:["stoic-week-handbook","stoic-training-trial","stoic-training-thesis"]}},{schemaVersion:2,revision:2,id:"stoic-6",courseId:"stoic",locale:"tr",title:"Hafta doluydu. Asıl işine sıra geldi mi?",goal:"Kayıtlarına bak. Gelecek hafta için yararlı bir işi ve ona uygun tek koşulu koru.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yoğun bir haftaydı. Kaydettiğin hangi iş hedefin için işe yaradı?",reason:{id:"stoic-6-reason",label:"Asıl işine sıra gelsin diye neye daha az zaman ayıracaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["İşe yarayan en küçük işi korumak","İşleyen başlama anını kullanmak","Yaramayan ek ritüelleri bırakmak"]},why:{id:"stoic-6-why",label:"Asıl işine sıra gelsin diye neye daha az zaman ayıracaksın?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kolay bir iş seçmekle hedefe yarayan bir iş seçmek farklıdır. Zihinsel karşılaştırma ve planlama araştırmaları, yapılabilir isteği, sonucunu, gerçek engeli ve belirli bir yanıtı birleştirir. Ortalama faydalar mütevazı ve değişkendir. Yöntem başarı garantisi vermez. Her engeli senin kusuruna da dönüştürmez.","Aynı denemeyi toparla. Fırsatın oluşmadığı günler ve aralar dahil, gerçekte ne olduğunu anlatan kayıtları oku. Yararlı işi ve başlama anını koru; gerekirse tek bir koşulu değiştir. Sonra sıradaki en küçük işi dene. Yardım etmeyen araçları bırak. Sonuç hâlâ belirsiz olabilir, ama gelen bilgi planını değiştirebilir. Destek almak veya bırakmak hâlâ geçerli seçimlerdir; kursu bitirmek bunları ortadan kaldırmaz."],example:{title:"Kerem işleyeni koruyor",text:"Ertesi hafta pazartesi öğle molasında Kerem kayıtlarına bakıyor. Masadaki kısa zamanda iki kullanılabilir cümle yazmış. Başka bir deneme erişim olmadığı için durmuş. Aynı zamanı koruyor, eksik erişimi istiyor ve yeni bir proje cümlesi yazıyor. Fazladan canlandırmayı bırakıyor. Başvurusu hâlâ beklemede. Ama yeni planını hayal ettiği koşullara değil, kendi denemelerinde gördüğü koşullara göre düzenliyor."}},move:{invitation:"Hedefe yarayan işi koru. Sıradaki uygun fırsatını seç.",instructions:["Kayıtlarına bak; tek bir koşulu korumaya veya değiştirmeye karar ver.","İşe yarayan en küçük işi yap. Diğer araçlar isteğe bağlı kalsın."],prompts:[],suggestions:{action:["Projeyi anlatan yararlı işimi tekrarla","Durumu netleştiren sorumu yeniden kullan","Kaydımın gösterdiği desteği iste"],minimum:["Kullanabileceğim bir proje cümlesi yaz","Açık bir soru gönder","Belirli bir erişim talebi ilet"],cue:["Öğle molasından döndüğümde","Sonraki güvenli proje mesajımda","Sıradaki proje denememden önce"],place:["Her zamanki çalışma masamda","Güvenli bir mesajlaşmada","Planımı rahatça yapabildiğim yerde"],minutes:[2,5],fallback:["Denediğim daha küçük biçimini kullan","Sonraki erişilebilir fırsatı seç","Destek al veya bu uygunsuz planı bırak"],observation:["Hedefime yarayan cümlem","Seçtiğim başlama anının gelip gelmediği","Sınadığım koşulda ne yapabildiğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Projeyi anlatan yararlı işimi tekrarla",minimum:"Kullanabileceğim bir proje cümlesi yaz",minutes:2,cueHint:"Öğle molasından döndüğümde",placeHint:"Her zamanki çalışma masamda",obstacleHint:"Önceki küçük iş veya başlama anı artık koşullarıma uymuyor.",fallbackHint:"Denediğim daha küçük biçimini kullan",observationHint:"Hedefime yarayan cümlem"},stopRule:"Sürdürmekten önce güvenliğini ve gereken dinlenmeyi koru. Uygun olmayan planı değiştir, ara ver veya bırak.",accessibleAlternative:"Yapabildiğin bir işi sürdür, yardım al veya yalnızca desteği seç. Kurstaki her aracı kullanman gerekmiyor."},result:{question:"Sıradaki işe yarayan en küçük işi yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Hangi geri bildirim hâlâ önemli?"},judgment:{primary:{id:"stoic-6-decision",scenario:"Kerem, hangi proje örneklerinin işverenin şartlarına uyduğunu kontrol etti. Uygun bir örnekte hâlâ yaptığı işi anlatan cümle eksik. Kayıtları öğle molasında yazmanın işe yaradığını gösteriyor. Bugün on dakikası var.",question:"Hangi iş önceliğine en doğrudan hizmet eder?",options:[{id:"draft-relevant",text:"Denediği öğle molası anında uygun proje cümlesini yazsın; gerekirse kullanabileceği erişilebilir bir yedek yolu olsun.",feedback:"Bu seçim, hedefe yarayan işi ve kayıtların desteklediği koşulu koruyor. Kabul garantisi vermeden görülebilen bir parça oluşturuyor. Denemeyi kaydet; sonradan gelen bilgiyi yeni planında kullan."},{id:"advice-read",text:"On dakika başvuru önerileri okusun; daha fazla öneriyi değerlendirdikten sonra projeyi anlatacak hangi işi yapacağını seçsin.",feedback:"Eksik bilgi varsa öneriler yardımcı olur. Burada gereken örnek ve işleyen başlama anı biliniyor. Daha çok okumak, mevcut zamana sığan yararlı parçayı yazmayı erteliyor. Şimdi o parçayı dene."},{id:"check-relevance-again",text:"Önceki proje cümlelerini yeniden değerlendirsin ve işverenin şartlarına en çok uyan cümleyi bu zamanda seçsin.",feedback:"Şartlar veya uygunluk belirsizse kontrol yararlıdır. Kerem bunlara zaten baktı ve bu örnekte cümle eksik. Mevcut yazma zamanını kullan. Şartlar değişirse tekrar kontrol edebilirsin."}],bestOptionId:"draft-relevant"}},carry:{takeaway:"Yararlı işi ve uygun koşulu koru. Gelen yeni bilgi sıradaki denemeni geliştirsin.",followUp:{questionId:"stoic-6-return",question:"Seçtiğin koşul yardım etti mi, işlemedi mi, sınanmadı mı? Yoksa hâlâ emin değil misin?",observationPrompt:"Hangi koşul oluştu ve gerçekte hangi işi yapmayı denedin?",adjustmentPrompt:"Tekrarla, bir koşulu değiştir, destek al veya bırak: hangisi uygun?"}},goDeeper:{sections:[{heading:"Toparlarken hedefe yarayan kanıta bak",paragraphs:["Epiktetos’un ayrımı, çabayı yönlendiren felsefi bir öneridir [S09]. Yaptığın işin sonuçlarını görmezden gelmeni gerektirmez. Gelen yanıt, işlemeyen erişim yolu veya tekrarlayan anlaşmazlık, sırada neyi deneyeceğini gösterebilir. İşverenin kararını tek başına veremezsin. Yine de uygun geri bildirimden yararlanabilir ve yardım arayabilirsin. Kaydın yaptığın işi ve ilgili sonucu birlikte içersin. İkisinden birini bütün karakterin hakkında hükme dönüştürme. Sonuç istediğin gibi olmadığında da hangi kısmı yaptığını, hangi kısmı değiştirebileceğini ve nerede yardıma ihtiyaç duyduğunu görebilirsin.","“Şu olursa bunu yaparım” planları üzerine araştırmalar, farklı hedeflerde ve ortamlarda tanınabilir bir durumu seçilen davranışla eşleştirmeyi destekler [S03]. Bu biçim, yanıt yapılabilir ve hedefe uygunsa yararlıdır. “Öğle molasından sonra işe yarar bir proje cümlesi yaz” somut iştir. “Öğle molasından sonra işverene onaylat” dışarıdaki sonuçtur. Hazırlık veya öneri okumak uygun olabilir, ama doğru adlandır. Son ders yeni günlük ritüel eklemek yerine aynı denemeyi toparlar. Kursu tamamlamak, gerçek hayat uygulamasının kanıtı değildir. Sıradaki işi ayrı denemede kaydet; planı yapılmış sayma."]},{heading:"Bir istek, bir engel, yapılabilir bir yol",paragraphs:["Wang ve çalışma arkadaşları zihinsel karşılaştırmayla “şu olursa bunu yaparım” planlarını birleştiren yöntemi derledi [S04]. Sıra; yapılabilir istek, istenen sonuç, mevcut engel ve belirli bir yanıttır. 21 makalede 15.907 katılımcılı 24 bağımsız tahminde hedefe ulaşma ortalama olarak arttı: g = 0,336. %95 güven aralığı 0,229 ile 0,443’tü. Çalışmalar arası farklılık yüksekti: I² = %59,3. Kalite de değişiyordu. Bu, birleşik yöntemin güncel bir tahminidir; herkes için başarı oranı değildir. Ortalamayı kendine garanti veya son tarih gibi uygulama.","ODA’nın bu sıralamayı kısa kullanması ve haftalık kayıtlara bakması uyarlamadır. Herkese uyan süre veya bu akışın etkisi belirlenmedi. Kolay oyalanma işleri ya da kurstaki her alıştırma yerine, asıl önceliğe yarayan işi seç. Engel dışarıdaki tehlike, eksik imkân, hastalık veya bakım ihtiyacıysa yanıt destek, sınır, dinlenme ya da hedefi bırakmak olabilir. Sıradaki denemeyi planından ve değerlendirmenden ayrı kaydet. Duygunun değişmemesi veya dış sonucun belirsizliği, yaptığını bildirdiğin yararlı işi silmez. Bu kayıt sonraki fırsatta neyi koruyacağına veya değiştireceğine karar vermek için kullanılabilir."]}],sourceIds:["stoic-epictetus-iep","stoic-planning","stoic-mcii"]}}],k=[{id:"stoic-1",practice:["Bir hedef seç. Yapabileceğin işi, gereken desteği ve dışarıdaki sonuçları ayır.","Fark edebileceğin bir başlama anı ve işe yarayan en küçük iş belirle.","İşi yap. Hazırlık seçersen bunu belirt, sonraki kullanım fırsatını da seç."],correct:1,photo:{id:"1507525428034-b723cf961d3e",alt:"Berrak suyun kumla buluştuğu sakin kıyı"}},{id:"stoic-2",practice:["Bir olguyu henüz doğrulanmamış yorumundan ayır.","Gerçek zararı küçültmeden her iki taraftaki kanıta bak.","Bildiklerine dayanan bir soru sor, yanlış bilgiyi düzelt veya güvenli biçimde kendini koru."],correct:2,photo:{id:"1500534314209-a25ddb2bd429",alt:"Alacakaranlıkta puslu tepe sıraları"}},{id:"stoic-3",practice:["Aynı iş için gündelik ve gerçekçi bir engel seç. Canlandırma isteğe bağlı.","Yapabileceğin bir yol planla. Sıkıntın artarsa dur.","Gerekirse seçtiğin yolu kullan. Engel çıktı mı, kaydet."],correct:1,photo:{id:"1464822759023-fed622ff2c3b",alt:"Karlı dağların altında ormanlık vadiler"}},{id:"stoic-4",practice:["Gündelik, hafif bir durum seç. İstersen kendi adınla 60 saniye düşün.","Panik, kendinden veya çevrenden kopma hissi ya da istemsiz anılar gelirse dur veya atla.","Gerçeğe dayanan bir cümle söyle, talep ilet veya güvenli sınır koy ve kaydet."],correct:0,photo:{id:"1506905925346-21bda4d32df4",alt:"Bulut denizinin üstünden görülen dağ sıraları"}},{id:"stoic-5",practice:["Gerçek bir denemeye bak. Yararlı kısmı ve uymayan somut koşulu belirt.","Tek düzeltme seç. Cezaya dönen veya uykunu bozan değerlendirmeyi kısalt, başka zamana al ya da bırak.","Düzeltmeyi gerçek bir işte kullan. Değerlendirmeden ayrı kaydet."],correct:1,photo:{id:"1475924156734-496f6cac6ec1",alt:"Alacakaranlıkta kayalık kıyıya vuran dalgalar"}},{id:"stoic-6",practice:["Aynı hedef ve iş için gerçekten yaptığın denemeleri karşılaştır.","İşe yarayan en küçük işi koru, en fazla tek koşulu değiştir.","Hedefe yarayan sıradaki işi dene ve kaydet. Ek araçlar isteğe bağlı kalsın."],correct:2,photo:{id:"1502082553048-f009c37129b9",alt:"Açık arazide tek başına duran ağaç"}}];function s(a,t){const r=k[t],e=a.judgment.primary,n=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==n.id).map(i=>i.text);return l.splice(r.correct,0,n.text),{...r,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l,feedback:n.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}}const y={id:"stoic",title:"Yanıtı mı bekliyorsun? Yapabileceğin işe dön.",subtitle:"6 ders. Belirsizlikte harekete geç, yorumlarını kontrol et, işe yarayan denemeni gelecek haftaya taşı.",description:"Belirsizliğin geri plana ittiği bir hedef seç. Stoacı ayrımlar ve isteğe bağlı psikolojik araçlarla bildiklerine uygun bir iş yap, değerlendir ve uyarla.",scope:"Strese, aksamalara ve belirsizliğe daha dengeli karşılık vermek isteyen yetişkinler için. Burada Stoacılık duyguları bastırmak veya güçlü görünmek değildir. Duygularına yer var; uygulama sırada ne yaptığına bakar. Bu eğitim ve kişisel uygulamadır, terapi değildir; tedavinin yerini tutmaz. Kaygı, depresyon, travma veya istemsiz kaygılı düşünceler yaşıyorsan bazı alıştırmalar, özellikle aksama canlandırmak, sana uymayabilir. Lütfen bir uzmanla çalış. Krizdeysen veya kendine zarar vermeyi düşünüyorsan hemen bulunduğun yerdeki acil yardım numarasını ara.",outcome:"Hedefine bağlı bir deneme, gerçek işler, dürüst değerlendirmeler ve destekle sınırları içeren gelecek hafta planı.",photo:{id:"1439066615861-d1af74d74000",alt:"Durgun dağ gölünde ahşap iskele"},lang:"tr",lessons:d.map(s)};export{y as COURSE,d as LESSONS_V2,m as SOURCES};
